import {readFileSync,writeFileSync} from 'node:fs';
import {resolve,relative,dirname} from 'node:path';
import {Script} from 'node:vm';

// The site's named, local ES modules are packaged as classic-script factories.
// This keeps the editable modules and avoids file:// module/CORS restrictions.
export function bundleBrowser(entry='src/main.js',output='src/site.js'){
 const root=process.cwd(),done=new Set(),visiting=new Set(),factories=[];
 function visit(file){
  file=resolve(file);const key=relative(root,file).replaceAll('\\','/');
  if(done.has(file))return key;
  if(visiting.has(file))throw Error(`Cyclic browser import: ${key}`);
  if(key.startsWith('../')||!key.endsWith('.js'))throw Error(`Unsupported browser module: ${key}`);
  visiting.add(file);
  let code=readFileSync(file,'utf8');const bindings=[];
  code=code.replace(/^import\s*\{([^}]+)\}\s*from\s*['"]([^'"]+)['"];?[^\S\r\n]*$/gm,(_,names,specifier)=>{
   if(!specifier.startsWith('.'))throw Error(`Browser imports must be local: ${specifier}`);
   const dependency=visit(resolve(dirname(file),specifier));
   const destructure=names.split(',').map(name=>name.trim().replace(/\s+as\s+/,': ')).join(',');
   bindings.push(`const {${destructure}}=modules[${JSON.stringify(dependency)}];`);return'';
  });
  const exports=[];
  code=code.replace(/^export\s+(const|let|var|function)\s+([A-Za-z_$][\w$]*)/gm,(_,kind,name)=>{exports.push(name);return`${kind} ${name}`;});
  if(/^\s*(import|export)\b/m.test(code)||/\bimport\s*\(/.test(code))throw Error(`Unsupported module syntax in ${key}`);
  factories.push(`// ${key}\nmodules[${JSON.stringify(key)}]=(()=>{\n${bindings.join('\n')}\n${code}\nreturn {${exports.map(name=>`get ${name}(){return ${name};}`).join(',')}};\n})();`);
  visiting.delete(file);done.add(file);return key;
 }
 visit(entry);
 const bundle=`// Generated by node scripts/build.mjs. Edit src/main.js and its modules.\n(()=>{\n'use strict';\nconst modules=Object.create(null);\n${factories.join('\n\n')}\n})();\n`;
 new Script(bundle,{filename:output}); // Fail the build if the generated script is invalid.
 writeFileSync(output,bundle);console.log(`Browser script: ${done.size} modules → ${output}`);
}
